SELECT p.supplier_id, CASE WHEN p.stock_qty >= 302 THEN 'high' WHEN p.stock_qty >= 81 THEN 'mid' ELSE 'low' END AS stock_qty_bucket, COUNT(DISTINCT ss.revenue) AS unique_products FROM store_sales ss RIGHT JOIN products p ON ss.product_id = p.id JOIN suppliers s ON p.supplier_id = s.id GROUP BY p.supplier_id, CASE WHEN p.stock_qty >= 302 THEN 'high' WHEN p.stock_qty >= 81 THEN 'mid' ELSE 'low' END ORDER BY stock_qty_bucket DESC, supplier_id LIMIT 3;
